insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('1', 'ARCH-001', 'Problem Solver', 'A founder who believes meaningful companies begin with meaningful problems, and builds through careful reasoning and conviction.', '{"decision_style": "Data-led, but tends to stall waiting for certainty that never fully arrives.", "stress_pattern": "Overthinks, then withdraws — goes quiet rather than asking for help.", "core_motivation": "Purpose"}', 'Likely when the founder: repeatedly references lived experience behind the company; spends disproportionate time validating before acting; values evidence over speed; hesitates when information is incomplete; describes success in terms of customer outcomes rather than company status. Frequently says: "I just want to make sure we''re solving the right problem." / "I need a little more validation."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:05.172303+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('2', 'ARCH-002', 'Operator', 'A founder who believes in craftsmanship, and builds through speed and hands-on control.', '{"decision_style": "Intuition-led, moves fast, rarely waits for full information.", "stress_pattern": "Over-controls — takes on tasks personally instead of delegating.", "core_motivation": "Mastery"}', 'Likely when the founder: enjoys building more than pitching; personally fixes operational bottlenecks; prefers execution over strategy discussions; has difficulty trusting work until personally reviewed; consistently optimizes systems and processes. Frequently says: "I''ll just do it."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:06.21338+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('3', 'ARCH-003', 'Visionary Builder', 'A founder who believes companies should outlive their creators, and builds by aligning people around a long-term vision.', '{"decision_style": "Panel-advised, but the final decision always comes back to them.", "stress_pattern": "Over-controls — struggles to hand off strategic ownership.", "core_motivation": "Legacy"}', 'Likely when the founder: regularly discusses long-term impact; naturally recruits around mission; enjoys strategy more than operations; seeks input widely before deciding; sees themselves as steward rather than manager. Repeatedly says: "We''re building something much bigger than us."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:06.770751+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('4', 'ARCH-004', 'Market Maker', 'A founder who believes markets reward momentum, and builds through customer obsession and constant adaptation.', '{"decision_style": "Customer-led. Makes decisions by observing market reactions rather than internal certainty.", "stress_pattern": "Chases signals. Begins changing direction too frequently when feedback becomes noisy.", "core_motivation": "Influence"}', 'Likely when the founder: spends most time talking to customers; measures progress through adoption rather than product perfection; changes messaging rapidly; experiments continuously. Frequently says: "Let''s see what customers tell us."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:07.179777+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('5', 'ARCH-005', 'Systems Architect', 'A founder who believes scalable companies are engineered, and builds through structure, systems, and repeatability.', '{"decision_style": "Framework-led. Prefers repeatable systems over instinct.", "stress_pattern": "Optimizes internally while external execution slows.", "core_motivation": "Order"}', 'Likely when the founder: naturally creates SOPs; maps processes before acting; enjoys organizational design; thinks in workflows rather than events. Frequently asks: "Can this become a system?"', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:07.606027+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('6', 'ARCH-006', 'Catalyst', 'A founder who believes momentum creates opportunity, and builds by constantly opening new doors.', '{"decision_style": "Opportunity-led. Rapidly recognizes new possibilities and acts before complete certainty.", "stress_pattern": "Starts too many initiatives simultaneously.", "core_motivation": "Possibility"}', 'Likely when the founder: constantly identifies adjacent opportunities; gets energized by beginnings; becomes bored after stabilization; regularly pivots toward exciting possibilities. Often says: "We should try this too."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:08.03+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('7', 'ARCH-007', 'Community Builder', 'A founder who believes enduring companies are built by people first, and grows through trust, culture, and relationships.', '{"decision_style": "Relationship-aware. Considers team trust alongside business outcomes.", "stress_pattern": "Avoids difficult conversations to preserve harmony.", "core_motivation": "Connection"}', 'Likely when the founder: discusses team before metrics; invests heavily in culture; naturally mentors people; hesitates to remove underperformers. Often says: "I don''t want to lose the team."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:08.414213+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "archetypes" ("archetype_id", "archetype_code", "archetype_name", "description", "key_traits", "assignment_criteria", "linked_founder_dimension_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('8', 'ARCH-008', 'Challenger', 'A founder who believes extraordinary companies require extraordinary conviction, and builds by pushing beyond conventional limits.', '{"decision_style": "Conviction-led. Makes bold decisions even against consensus.", "stress_pattern": "Becomes increasingly combative and dismissive of opposing viewpoints.", "core_motivation": "Achievement"}', 'Likely when the founder: intentionally challenges assumptions; enjoys difficult competitive environments; values ambition over comfort; often acts despite criticism. Repeatedly says: "If everyone agrees, we''re probably late."', '[]', '2026-07-15 07:47:15.986623+00', '2026-08-03 03:07:08.843198+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
